import { useMemo, useState } from 'react';
import { JxBadge, JxChip, JxEmptyState, JxPagination, JxProgressCircle } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'completed';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

interface StatusMeta {
  value: ProjectStatus;
  label: string;
  tone: 'success' | 'warning' | 'danger' | 'alt';
}

const STATUSES: StatusMeta[] = [
  { value: 'active', label: 'Активен', tone: 'success' },
  { value: 'paused', label: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышена квота', tone: 'danger' },
  { value: 'completed', label: 'Завершён', tone: 'alt' },
];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас', quota: 42, status: 'active' },
  { id: 'p2', name: 'Кобальт', quota: 87, status: 'over' },
  { id: 'p3', name: 'Меридиан', quota: 15, status: 'paused' },
  { id: 'p4', name: 'Орбита', quota: 100, status: 'completed' },
  { id: 'p5', name: 'Призма', quota: 63, status: 'active' },
  { id: 'p6', name: 'Тундра', quota: 91, status: 'over' },
  { id: 'p7', name: 'Феникс', quota: 28, status: 'paused' },
  { id: 'p8', name: 'Циклон', quota: 55, status: 'active' },
  { id: 'p9', name: 'Эклипс', quota: 100, status: 'completed' },
  { id: 'p10', name: 'Янтарь', quota: 74, status: 'active' },
  { id: 'p11', name: 'Гранит', quota: 33, status: 'paused' },
  { id: 'p12', name: 'Дельта', quota: 96, status: 'over' },
];

const ALL_STATUSES = STATUSES.map((status) => status.value);
const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((current) =>
      current.includes(status) ? current.filter((value) => value !== status) : [...current, status],
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setSelectedStatuses((current) => current.filter((value) => value !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses(ALL_STATUSES);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => selectedStatuses.includes(project.status)),
    [selectedStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {STATUSES.map((status) => (
          <JxChip
            key={status.value}
            active={selectedStatuses.includes(status.value)}
            removable
            onClick={() => toggleStatus(status.value)}
            onRemove={() => removeStatus(status.value)}
          >
            {status.label}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          message="Попробуйте вернуть отключённые статусы, чтобы увидеть больше проектов."
          action={
            <button type="button" className="jx-btn jx-btn--primary" onClick={resetFilters}>
              Сбросить фильтры
            </button>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {visible.map((project) => {
              const statusMeta = STATUSES.find((status) => status.value === project.status)!;
              return (
                <div
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: '16px',
                    padding: '12px 0',
                    borderBottom: '1px solid var(--jx-border)',
                  }}
                >
                  <span style={{ color: 'var(--jx-text)' }}>{project.name}</span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                    <JxProgressCircle value={project.quota} showValue />
                    <JxBadge tone={statusMeta.tone} dot>
                      {statusMeta.label}
                    </JxBadge>
                  </div>
                </div>
              );
            })}
          </div>

          {pageCount > 1 && <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />}
        </>
      )}
    </div>
  );
}

